/// SHA-256 of [`INCY_SIGNERS`]'s single certificate, pinned by the tests.
pub const INCY_SIGNER_SHA256: [&str; 1] =
    ["e1430d81de511c72253a6a409910e609686f084e3944eab6f154999ac7128b13"];

#[cfg(test)]
mod tests {
    use super::*;
    use sha2::{Digest, Sha256};

    #[test]
    fn incy_signers_are_pinned() {
        assert_eq!(INCY_PACKAGE, "llc.itdev.incy");
        assert_eq!(INCY_SIGNERS.scheme, SigScheme::V3);
        assert_eq!(INCY_SIGNERS.apk_version, crate::release::INCY_VERSION);
        assert_eq!(INCY_SIGNERS.certs.len(), 1);
        assert_eq!(INCY_SIGNERS.certs[0].len(), 1420);

        let digest = Sha256::digest(INCY_SIGNERS.certs[0]);
        let hex: String = digest.iter().map(|b| format!("{b:02x}")).collect();
        assert_eq!([hex.as_str()], INCY_SIGNER_SHA256);
    }

    /// The certificate must stay a parseable X.509 structure: a truncated regeneration would
    /// still hash to nothing useful but would fail here.
    #[test]
    fn the_certificate_is_well_formed_der() {
        let cert = INCY_SIGNERS.certs[0];
        assert_eq!(cert[0], 0x30, "SEQUENCE");
        assert_eq!(
            u16::from_be_bytes([cert[2], cert[3]]) as usize + 4,
            cert.len()
        );
    }
}
